INSERT OR IGNORE INTO tax_free_rule_versions (id,territory_id,version_number,lifecycle,availability,program_name,summary,eligibility_json,purchases_json,store_steps_json,documents_json,goods_json,deadlines_json,customs_json,electronic_validation_json,payout_json,disclaimer,effective_from,effective_to,content_verified_at,source_checked_at,published_at,published_by,supersedes_version_id,created_at,updated_at) VALUES ('tf-ae-world-v1','tf-ae',1,'published','partial','Tourist VAT Refund Scheme','The UAE operates a digital tourist VAT refund scheme through registered retailers and validation points at air, land and sea exits.','["Eligibility depends on residence and visitor status under the local rules"]','["Only qualifying goods from participating retailers; exclusions vary by country"]','["Confirm participation before paying","Ask for the required tax-free document and verify every personal detail"]','["Passport or accepted travel document","Original receipt or invoice","Tax-free form or electronic record when required"]','["Keep goods unused and accessible when the local procedure requires inspection"]','{"review":"Open the linked country source for current export and filing deadlines"}','["Follow the official final-departure procedure and complete validation before baggage check-in when instructed"]','["Electronic validation confirms export; it does not necessarily pay the refund"]','["The retailer or named operator pays the refund after required validation","Fees and payout timing depend on the local program and operator"]','Tripto has verified evidence that a traveler tax-free route exists, but this country record is partial. Confirm thresholds, eligibility, deadlines, airports and fees in the linked source before purchase and departure.','2026-09-27',NULL,1790467200000,1790467200000,1790467200000,'world-directory-review',NULL,1790467200000,1790467200000);

